@@ -0,0 +1,49 @@
+import { test } from 'node:test'
+import assert from 'node:assert/strict'
+import { JsonStore } from '../src/store.js'
+import { tmpdir } from 'node:os'
+import { join } from 'node:path'
+import { rmSync, existsSync, readFileSync } from 'node:fs'
+
+test('JsonStore load/save and directory creation', async () => {
+  const file = join(tmpdir(), `bookstore-test-${Date.now()}-store.json`)
+  try {
+    const store = new JsonStore(file)
+    // missing file -> null
+    assert.equal(await store.load(), null)
+    const data = [{ id: 'x', title: 'X', author: 'A', priceCents: 100, stock: 1 }]
+    await store.save(data)
+    assert.ok(existsSync(file))
+    const raw = readFileSync(file, 'utf8')
+    assert.equal(JSON.parse(raw).length, 1)
+  } finally {
+    try { rmSync(file) } catch {}
+  }
+})
+
+test('Inventory.fromStore loads data and persists only on successful ops', async () => {
+  const file = join(tmpdir(), `bookstore-test-${Date.now()}-invstore.json`)
+  try {
+    const initial = [{ id: 'p', title: 'P', author: 'P', priceCents: 100, stock: 2 }]
+    // write initial file
+    const store = new JsonStore(file)
+    await store.save(initial)
+    const inv = await (await import('../src/inventory.js')).Inventory.fromStore(store, [])
+    // loaded from store
+    assert.equal(inv.find('p').stock, 2)
+    // successful add persists
+    await inv.add({ id: 'p' }, 1)
+    const raw = readFileSync(file, 'utf8')
+    const saved = JSON.parse(raw)
+    const p = saved.find((b) => b.id === 'p')
+    assert.equal(p.stock, 3)
+    // failed remove (unknown) should not write
+    let before = readFileSync(file, 'utf8')
+    await assert.rejects(() => inv.remove('zzz', 1))
+    let after = readFileSync(file, 'utf8')
+    assert.equal(before, after)
+  } finally {
+    try { rmSync(file) } catch {}
+  }
+})
